<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Environment=ZENOH_ROUTER_CONFIG_URI=/opt/ros/jazzy/share/rmw_zenoh_cpp/config/DEFAULT_RMW_ZENOH_ROUTER_CONFIG.json5</span></span>
