<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ExecStart=/bin/bash -ec &#39;source /opt/ros/jazzy/setup.bash; exec /opt/ros/jazzy/lib/rmw_zenoh_cpp/rmw_zenohd&#39;</span></span>
